var ENT=[["Lighthouse", "Automated audits for performance and SEO."], ["WCAG", "Web accessibility guidelines."], ["Vite", "Instant dev server and bundler."], ["esbuild", "Extremely fast JS bundler."], ["React", "Meta's component UI library; the dominant way to build interactive web front ends."], ["Vue", "Evan You's progressive framework balancing approachability with power."], ["Svelte", "A compiler-first framework shifting work to build time for tiny fast bundles."]];
var TECH=[["Semantic HTML", "Using header, nav, main and article so pages mean what they say."], ["Responsive design", "Fluid grids and media queries adapting layouts to any screen."], ["Server-side rendering", "Rendering HTML on the server for fast first paint and SEO."], ["Static generation", "Pre-building pages at deploy time for speed and simplicity."], ["Progressive enhancement", "Core content working without JS, enhanced where supported."], ["Accessibility auditing", "Keyboard, contrast and screen-reader checks as part of the build."], ["Image optimization", "Responsive srcset, modern formats and lazy loading."], ["SEO metadata", "Titles, descriptions, canonicals and structured data per page."], ["Component composition", "Building pages from reusable, tested UI units."], ["Form validation", "Client hints plus server-truth validation on every input."]];
